export type CardCategory = 'chi_sono' | 'cosa_sono' | 'dove_sono' | 'hard_ass';

const FOLDERS: Record<CardCategory, string> = {
  chi_sono: 'carte_chi_sono',
  cosa_sono: 'carte_cosa_sono',
  dove_sono: 'carte_dove_sono',
  hard_ass: 'carte_hard_ass',
};

export function getCardPath(category: CardCategory, filename: string): string {
  return BASE + '/' + FOLDERS[category] + '/' + filename;
}

export function drawCard(cards: string[], usedIndices: number[]): { index: number; filename: string } | null {
  const available = cards.map((_, i) => i).filter(i => !usedIndices.includes(i));
  if (available.length === 0) return null;
  const idx = available[Math.floor(Math.random() * available.length)];
  return { index: idx, filename: cards[idx] };
}